update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Raa Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 1,800 residents"},{"label":"Size","value":"1.5 km long, 0.9 km wide"},{"label":"Distance from Male","value":"160 km"},{"label":"Transfer Options","value":"Seaplane or domestic flight + speedboat"},{"label":"Known For","value":"Authentic culture, pristine beaches, excellent snorkeling"},{"label":"Best For","value":"Cultural enthusiasts, beach lovers, snorkelers, authentic travelers"}],"island_overview":["Alifushi Island is an authentic local island in Raa Atoll that offers visitors a genuine glimpse into traditional Maldivian life. This charming island combines natural beauty with an authentic atmosphere, providing an ideal destination for travelers seeking real cultural experiences and pristine natural splendor.","Known for its pristine beaches, crystal-clear lagoons, and excellent house reef, Alifushi provides wonderful opportunities for snorkeling, swimming, and marine exploration. The island''s authentic community embraces visitors with traditional Maldivian warmth and shares their genuine way of life with sincere hospitality.","What makes Alifushi special is its authentic beauty and traditional natural setting. Visitors can enjoy pristine beaches, explore diverse marine life, and experience genuine island culture while staying in comfortable accommodations that showcase the authentic Maldivian lifestyle."],"island_sections":[{"heading":"Location & Map","paragraphs":["Alifushi Island is strategically located in the northern part of Raa Atoll, approximately 160 kilometers from Male. This location provides an authentic and genuine experience while maintaining good accessibility to the capital and international airport through various transfer options.","The island''s position offers excellent protection from strong currents while providing access to pristine coral reefs and diverse marine ecosystems. Its location in the atoll makes it an ideal base for exploring the authentic beauty and cultural richness of Raa Atoll."]},{"heading":"Alifushi: Authentic Paradise & Marine Genuineness","paragraphs":["Alifushi Island is blessed with exceptional natural beauty, featuring pristine white sand beaches, crystal-clear turquoise waters, and one of the most authentic marine environments in Raa Atoll. The island offers perfect conditions for beach relaxation and marine exploration in a genuine, traditional setting."]},{"heading":"Pristine White Sand Beaches","paragraphs":["Alifushi features genuine white sand beaches with gentle slopes and calm waters, perfect for swimming, sunbathing, and authentic beach activities."]},{"heading":"Authentic House Reef Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and offers genuine snorkeling with diverse marine life and colorful coral formations."]},{"heading":"Authentic Community Life","paragraphs":["Experience the genuine spirit of traditional island life with authentic locals and traditional Maldivian culture in a real community setting."]},{"heading":"Authentic Sandbank Adventures","paragraphs":["Explore nearby uninhabited sandbanks and pristine islands around Alifushi for genuine tropical paradise experiences with authentic marine life."]},{"heading":"Beach Features","paragraphs":["Alifushi''s coastal highlights include:"]},{"heading":"Marine Environment","paragraphs":["The waters around Alifushi feature:"]},{"heading":"Activities & Experiences","paragraphs":["Alifushi offers a perfect blend of marine adventures, cultural experiences, and authentic activities. The island''s genuine environment and traditional atmosphere provide ideal conditions for various activities in a real, authentic setting."]},{"heading":"Authentic House Reef Snorkeling","paragraphs":["Explore the genuine house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility in authentic waters."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover nearby genuine dive sites with professional dive operators offering guided dives and certification courses in authentic marine environments."]},{"heading":"Island Hopping Adventures","paragraphs":["Visit nearby islands, pristine sandbanks, and discover the authentic beauty of Raa Atoll with genuine exploration opportunities."]},{"heading":"Traditional Fishing","paragraphs":["Experience authentic Maldivian fishing techniques with local fishermen during sunset and night fishing trips in genuine community settings."]},{"heading":"Authentic Cultural Immersion","paragraphs":["Learn about local traditions, participate in community activities, and experience genuine Maldivian island life with traditional cultural exchanges."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy magical sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing in authentic waters."]},{"heading":"Community Life & Culture","paragraphs":["Alifushi is home to approximately 1,800 residents who maintain traditional Maldivian ways of life while embracing sustainable tourism. The island''s community is known for their exceptional friendliness, hospitality, and authentic cultural traditions that create a genuine atmosphere for visitors."]},{"heading":"Island Life","paragraphs":["Daily life on Alifushi follows traditional patterns centered around fishing, family, and community activities. The island maintains an authentic atmosphere where visitors can experience genuine Maldivian culture and customs in their most traditional, real setting."]},{"heading":"Local Traditions","paragraphs":["The community preserves traditional Maldivian practices including traditional music, dance, handicrafts, and fishing techniques. Visitors can observe and often participate in cultural activities and celebrations in this authentic island environment."]},{"heading":"Sustainable Tourism","paragraphs":["Alifushi has embraced sustainable tourism practices that benefit the local community while preserving the island''s natural environment and authentic cultural heritage for future generations to experience and enjoy."]}],"island_faqs":[{"question":"How do I get to Alifushi Island?","answer":"Regular ferry services are also available from Male and nearby islands in Raa Atoll."},{"question":"What is the best time to visit Alifushi?","answer":"The best time to visit Alifushi is during the dry season from December to April when weather conditions are most favorable for beach activities and water sports. However, the island can be visited year-round with the wet season offering fewer crowds and a more authentic local atmosphere."},{"question":"What accommodation options are available on Alifushi?","answer":"Alifushi offers various budget-friendly accommodations including authentic guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, and meal packages in a genuine setting."},{"question":"What makes Alifushi''s community special?","answer":"Alifushi is known for its authentic and genuine community atmosphere. The island maintains traditional Maldivian cultural practices while welcoming visitors with warm hospitality. Visitors can experience real cultural exchanges and participate in community activities in this traditional setting."}],"island_nearby_slugs":["rasgetheemu","ungoofaaru","rasmaadhoo","vaadhoo","angolhitheemu","dhuvaafaru","fainu","hulhudhuffaaru","inguraidhoo","innamaadhoo","kinolhas","maakurathu","maduvvaree","meedhoo"]}'::jsonb
